function FlagIcon({ country }) {
  const w = 20, h = 14;
  const common = { width: w, height: h, className: "shrink-0 rounded-sm", style: { display: "block" } };

  if (country === "Canada") {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="20" height="14" fill="#FFFFFF" />
        <rect x="0" width="5" height="14" fill="#D52B1E" />
        <rect x="15" width="5" height="14" fill="#D52B1E" />
        <path d="M10 3 L11 6 L13.5 5 L12.3 7.5 L14 7.8 L11.8 9.3 L12.3 11.5 L10 10.3 L7.7 11.5 L8.2 9.3 L6 7.8 L7.7 7.5 L6.5 5 L9 6 Z" fill="#D52B1E" />
      </svg>
    );
  }
  if (country === "USA") {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="20" height="14" fill="#FFFFFF" />
        {[0, 1, 2, 3, 4, 5, 6].map((i) => (
          <rect key={i} y={i * 2} width="20" height="1" fill="#B22234" />
        ))}
        <rect width="9" height="7.5" fill="#3C3B6E" />
      </svg>
    );
  }
  if (country === "France") {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="6.67" height="14" fill="#0055A4" />
        <rect x="6.67" width="6.67" height="14" fill="#FFFFFF" />
        <rect x="13.34" width="6.67" height="14" fill="#EF4135" />
      </svg>
    );
  }
  if (country === "Poland") {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="20" height="7" fill="#FFFFFF" />
        <rect y="7" width="20" height="7" fill="#DC143C" />
      </svg>
    );
  }
  if (country === "Belarus") {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="20" height="9.5" fill="#C8313E" />
        <rect y="9.5" width="20" height="4.5" fill="#4AA657" />
        <rect width="3" height="14" fill="#FFFFFF" />
        <rect width="3" height="14" fill="#C8313E" opacity="0.5" />
      </svg>
    );
  }
  if (country === "Finland") {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="20" height="14" fill="#FFFFFF" />
        <rect x="6" width="4" height="14" fill="#003580" />
        <rect y="5" width="20" height="4" fill="#003580" />
      </svg>
    );
  }
  const stripes = FLAG_STRIPES[country];
  if (stripes) {
    return (
      <svg {...common} viewBox="0 0 20 14">
        <rect width="20" height="4.67" y="0" fill={stripes[0]} />
        <rect width="20" height="4.67" y="4.67" fill={stripes[1]} />
        <rect width="20" height="4.67" y="9.34" fill={stripes[2]} />
      </svg>
    );
  }
  return null;
}

