function Badge({ children, tone = "neutral" }) {
  const tones = {
    win: { bg: "rgba(46,158,89,0.15)", color: "#5FD68A", border: "#1F6B41" },
    loss: { bg: "rgba(200,16,46,0.15)", color: "#FF7A8A", border: C.redDeep },
    ot: { bg: "rgba(139,146,154,0.12)", color: C.muted, border: C.line },
    neutral: { bg: "transparent", color: C.muted, border: C.line },
  };
  const t = tones[tone];
  return (
    <span
      className="text-xs font-bold px-2 py-1 rounded"
      style={{ background: t.bg, color: t.color, border: `1px solid ${t.border}`, fontFamily: FONTS.mono, letterSpacing: "0.05em" }}
    >
      {children}
    </span>
  );
}

function SectionHeading({ season, title }) {
  const league = isCancelled(season) ? "IJNL" : `IJNL \u00b7 ${divisionLabel(season).toUpperCase()}`;
  return (
    <div className="mb-6">
      <div
        className="text-xs font-bold"
        style={{ color: C.red, fontFamily: FONTS.mono, letterSpacing: "0.15em" }}
      >
        {league}
      </div>
      <div
        className="text-xs font-bold mb-1"
        style={{ color: C.muted, fontFamily: FONTS.mono, letterSpacing: "0.15em" }}
      >
        SEASON {season}
      </div>
      <h2
        className="text-3xl sm:text-4xl"
        style={{ fontFamily: FONTS.display, color: C.white, letterSpacing: "0.01em" }}
      >
        {title}
      </h2>
    </div>
  );
}

function SampleNote({ children }) {
  return (
    <div
      className="mb-6 px-4 py-3 rounded text-sm"
      style={{ background: "rgba(200,16,46,0.08)", border: `1px dashed ${C.redDeep}`, color: C.muted, fontFamily: FONTS.body }}
    >
      {children}
    </div>
  );
}

function SortHeader({ label, active, dir, align = "right", onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`flex items-center gap-1 ${align === "right" ? "justify-end w-full" : ""}`}
      style={{ color: active ? C.white : C.muted, background: "none", border: "none", padding: 0, cursor: "pointer", fontFamily: FONTS.mono, fontSize: "inherit", letterSpacing: "inherit" }}
    >
      {label}
      <span style={{ fontSize: 9, opacity: active ? 1 : 0.35, color: active ? C.red : C.muted }}>
        {active ? (dir === "asc" ? "\u25B2" : "\u25BC") : "\u25BC"}
      </span>
    </button>
  );
}

function ConferenceTable({ title, teams }) {
  const cols = "2.4fr repeat(8, minmax(34px, 0.7fr))";
  const [sortKey, setSortKey] = useState(null);
  const [sortDir, setSortDir] = useState("desc");

  function handleSort(key) {
    if (sortKey === key) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDir(key === "team" ? "asc" : "desc");
    }
  }

  const sortedTeams = useMemo(() => {
    if (!sortKey) return teams;
    const arr = teams.slice();
    arr.sort((a, b) => {
      if (sortKey === "team") {
        return sortDir === "asc" ? a.team.localeCompare(b.team) : b.team.localeCompare(a.team);
      }
      const av = sortKey === "gd" ? parseInt(a.gd, 10) : Number(a[sortKey]);
      const bv = sortKey === "gd" ? parseInt(b.gd, 10) : Number(b[sortKey]);
      return sortDir === "asc" ? av - bv : bv - av;
    });
    return arr;
  }, [teams, sortKey, sortDir]);

  const cols_ = [
    { key: "gp", label: "GP" },
    { key: "w", label: "W" },
    { key: "l", label: "L" },
    { key: "t", label: "T" },
    { key: "gf", label: "GF" },
    { key: "ga", label: "GA" },
    { key: "gd", label: "GD" },
    { key: "pts", label: "PTS" },
  ];

  return (
    <div>
      <h3 style={{ fontFamily: FONTS.mono, color: C.muted, fontSize: 12, letterSpacing: "0.1em", marginBottom: 10 }}>
        {title.toUpperCase()}
      </h3>
      <div className="rounded-lg overflow-x-auto" style={{ border: `1px solid ${C.line}` }}>
        <div style={{ minWidth: 560 }}>
          <div
            className="grid px-4 sm:px-5 py-2 text-xs"
            style={{ gridTemplateColumns: cols, background: C.surface2, color: C.muted, fontFamily: FONTS.mono, letterSpacing: "0.05em" }}
          >
            <SortHeader label="TEAM" align="left" active={sortKey === "team"} dir={sortDir} onClick={() => handleSort("team")} />
            {cols_.map((c) => (
              <SortHeader key={c.key} label={c.label} active={sortKey === c.key} dir={sortDir} onClick={() => handleSort(c.key)} />
            ))}
          </div>
          {sortedTeams.map((r, i) => {
            const us = r.team === "Amsterdam Mustangs";
            return (
              <div
                key={r.team}
                className="grid px-4 sm:px-5 py-2 text-sm items-center"
                style={{
                  gridTemplateColumns: cols,
                  background: us ? "rgba(200,16,46,0.1)" : C.surface,
                  borderTop: `1px solid ${C.line}`,
                  fontWeight: us ? 700 : 400,
                }}
              >
                <span className="flex items-center gap-2 truncate" style={{ color: C.white }}>
                  <span style={{ flexShrink: 0 }}>{i + 1}.</span>
                  {(us ? LOGO : opponentLogo(r.team)) && (
                    <img src={us ? LOGO : opponentLogo(r.team)} alt="" aria-hidden className="w-10 h-10 object-contain shrink-0" />
                  )}
                  <span className="truncate">{r.team}</span>
                </span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.gp}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.w}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.l}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.t}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.gf}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.ga}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.muted }}>{r.gd}</span>
                <span className="text-right" style={{ fontFamily: FONTS.mono, color: C.red, fontWeight: 700 }}>{r.pts}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function StatsTable({ title, columns, rows, highlightKey }) {
  const cols = `2fr repeat(${columns.length - 1}, minmax(30px, 0.6fr))`;
  const [sortKey, setSortKey] = useState(null);
  const [sortDir, setSortDir] = useState("desc");

  function handleSort(key) {
    if (sortKey === key) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDir(key === "name" ? "asc" : "desc");
    }
  }

  const sortedRows = useMemo(() => {
    if (!sortKey) return rows;
    const arr = rows.slice();
    arr.sort((a, b) => {
      const av = a[sortKey];
      const bv = b[sortKey];
      const an = parseFloat(av);
      const bn = parseFloat(bv);
      if (!isNaN(an) && !isNaN(bn)) {
        return sortDir === "asc" ? an - bn : bn - an;
      }
      return sortDir === "asc" ? String(av).localeCompare(String(bv)) : String(bv).localeCompare(String(av));
    });
    return arr;
  }, [rows, sortKey, sortDir]);

  return (
    <div>
      <h3 style={{ fontFamily: FONTS.mono, color: C.muted, fontSize: 12, letterSpacing: "0.1em", marginBottom: 10 }}>
        {title.toUpperCase()}
      </h3>
      <div className="rounded-lg overflow-x-auto" style={{ border: `1px solid ${C.line}` }}>
        <div style={{ minWidth: 480 }}>
          <div
            className="grid px-4 sm:px-5 py-2 text-xs"
            style={{ gridTemplateColumns: cols, background: C.surface2, color: C.muted, fontFamily: FONTS.mono, letterSpacing: "0.05em" }}
          >
            {columns.map((c) => (
              <SortHeader
                key={c.key}
                label={c.label.toUpperCase()}
                align={c.key === "name" ? "left" : "right"}
                active={sortKey === c.key}
                dir={sortDir}
                onClick={() => handleSort(c.key)}
              />
            ))}
          </div>
          {sortedRows.map((row, ri) => (
            <div
              key={ri}
              className="grid px-4 sm:px-5 py-3 text-sm items-center"
              style={{ gridTemplateColumns: cols, background: C.surface, borderTop: `1px solid ${C.line}` }}
            >
              {columns.map((c) => (
                <span
                  key={c.key}
                  className={c.key === "name" ? "" : "text-right truncate"}
                  style={{
                    color: c.key === highlightKey ? C.red : c.key === "name" ? C.white : C.muted,
                    fontFamily: c.key === "name" ? FONTS.body : FONTS.mono,
                    fontWeight: c.key === highlightKey ? 700 : c.key === "name" ? 600 : 400,
                  }}
                >
                  {row[c.key]}
                </span>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const INFRACTION_LABELS = {
  TRIP: "Tripping",
  HOLD: "Holding",
  ROUGH: "Roughing",
  HOOK: "Hooking",
  "HI-ST": "High-sticking",
  "ILL-H": "Body checking", // confirmed via BenchApp export (gamesheet used shorthand)
  INTRF: "Interference",
  BOARD: "Boarding",
  "UN-SP": "Unsportsmanlike conduct", // confirmed via BenchApp export
  "CHE-B": "Checking from behind", // confirmed via BenchApp export
  SLASH: "Slashing",
  "TOO-M": "Too many men on the ice",
  DELAY: "Delay of game",
};

function PeriodLabel({ period }) {
  return period <= 3 ? `P${period}` : "OT";
}

